package com.tsuyu.line;

import org.json.JSONObject;

import java.util.*;

public final class SourceEngine {
    private static final String[] PLAY={"henta","yoru","yummy","anilibria","anixsekai","animevost","animelib","animelib4k","animedia","animetka","anidub","kodik"};
    private static final String[] DISCOVER={"kodik","anilibria","anixsekai","animevost","animelib","animelib4k","animedia","animetka","anidub"};
    private static final HashMap<String,Integer> BASE=new HashMap<>();
    static {BASE.put("yoru",106);BASE.put("kodik",104);BASE.put("yummy",100);BASE.put("anilibria",94);BASE.put("anixsekai",90);BASE.put("animevost",88);BASE.put("animelib4k",84);BASE.put("animelib",80);BASE.put("animedia",72);BASE.put("animetka",66);BASE.put("anidub",64);BASE.put("hanime",40);}
    private static boolean playable(String s){return s!=null&&Arrays.asList(PLAY).contains(s);}
    private static JSONObject snapshot(){YoruApp app=YoruApp.app();return app==null||app.store==null?new JSONObject():app.store.sourceSnapshot();}
    static ArrayList<String> playbackOrder(Anime input){if(input!=null&&"henta".equals(input.source))return new ArrayList<>(Arrays.asList("henta"));LinkedHashSet<String> set=new LinkedHashSet<>();if(input!=null&&playable(input.source)&&!input.metadataOnly())set.add(input.source);ArrayList<String> pool=new ArrayList<>(Arrays.asList(PLAY));filterForAudience(pool,input);pool.sort((a,b)->score(b,input)-score(a,input));for(String s:pool)if(!set.contains(s))set.add(s);return new ArrayList<>(set);}
    static ArrayList<String> discoveryOrder(Anime original,Anime shell){ArrayList<String> pool=new ArrayList<>(Arrays.asList(DISCOVER));Anime base=shell==null?original:shell;filterForAudience(pool,base);pool.sort((a,b)->score(b,base)-score(a,base));return pool;}
    private static boolean hasConcreteVoice(){try{return !ApiRepository.voiceKey(YoruApp.app().store.voicePreference()).isEmpty()||!YoruApp.app().store.favoriteVoices().isEmpty();}catch(Exception e){return false;}}
    private static int voiceBoost(String source){try{ArrayList<String> voices=YoruApp.app().store.favoriteVoices();String direct=YoruApp.app().store.voicePreference();if(!direct.isEmpty()&&!voices.contains(direct))voices.add(0,direct);if(voices.isEmpty())return 0;int best=-10;String s=sourceId(source);for(int i=0;i<voices.size();i++){String key=ApiRepository.voiceKey(voices.get(i));if(key.isEmpty())continue;int base=Math.max(8,62-i*7);if(key.equals("anidub")&&s.equals("anidub"))best=Math.max(best,base);else if(key.equals("animevost")&&s.equals("animevost"))best=Math.max(best,base);else if(key.equals("animedia")&&s.equals("animedia"))best=Math.max(best,base);else if(key.equals("anilibria")&&(s.equals("anilibria")||s.equals("animelib")||s.equals("animelib4k")))best=Math.max(best,Math.max(6,base-8));else if((key.equals("animaunt")||key.equals("anistar-deep")||key.equals("beyond-studio")||key.equals("dreamcast")||key.equals("studio-band")||key.equals("jam")||key.equals("shiza")||key.equals("subtitles"))&&(s.equals("yummy")||s.equals("anixsekai")||s.equals("kodik")||s.equals("animetka")))best=Math.max(best,Math.max(4,base-24));}return best;}catch(Exception e){return 0;}}
    static boolean isHentai(Anime a){if(a==null)return false;if("hanime".equals(a.source))return true;for(String g:a.genres){String t=g==null?"":g.trim().toLowerCase(Locale.ROOT);if(t.contains("хентай")||t.contains("hentai"))return true;}return false;}
    static void filterForAudience(ArrayList<String> pool,Anime base){if(pool==null)return;if(isHentai(base))pool.removeIf(s->s==null||s.equals("anilibria")||s.equals("animevost")||s.equals("animelib")||s.equals("animelib4k")||s.equals("animedia"));else pool.removeIf(s->"hanime".equals(s));}
    static int score(String source,Anime input){String s=sourceId(source);int v=BASE.containsKey(s)?BASE.get(s):45;v+=voiceBoost(s);JSONObject row=snapshot().optJSONObject(s);if(row!=null){int ok=row.optInt("ok"),fail=row.optInt("fail"),total=ok+fail;if(total>0)v+=(ok*46/Math.max(1,total))-Math.min(42,fail*7);long avg=row.optLong("avg",0);if(avg>0)v-=Math.min(30,(int)(avg/850));if(row.optLong("lastBad",0)>System.currentTimeMillis()-20*60*1000)v-=24;if(row.optLong("lastOk",0)>System.currentTimeMillis()-30*60*1000)v+=12;int failRun=row.optInt("failRun",0);if(failRun>=2)v-=Math.min(76,failRun*19);if(total>=5&&fail>ok)v-=Math.min(52,(fail-ok)*9);if(total>=3&&ok>fail)v+=Math.min(24,(ok-fail)*6);v+=Math.min(18,row.optInt("quality",0)/120);v+=Math.min(16,row.optInt("variants",0));}boolean hentai=isHentai(input);if(hentai&&s.equals("hanime"))v+=95;else if(hentai&&(s.equals("kodik")||s.equals("yummy")||s.equals("anixsekai")))v+=15;else if(hentai&&(s.equals("anilibria")||s.equals("animevost")||s.equals("animelib")||s.equals("animelib4k")||s.equals("animedia")))v-=80;else if(!hentai&&s.equals("hanime"))v-=60;if(input!=null){if(s.equals(input.source))v+=20;if(input.libriaAlias!=null&&!input.libriaAlias.isEmpty()&&s.equals("anilibria"))v+=18;if(input.malId>0&&(s.equals("yummy")||s.equals("kodik")||s.equals("yoru")))v+=12;if(input.kpId>0&&s.equals("kodik"))v+=10;if(input.episodes>0&&input.episodes<=2&&(s.equals("kodik")||s.equals("animelib")))v+=5;}return v;}
    static void record(String source,boolean ok,long ms,int episodes,int variants,int quality){YoruApp app=YoruApp.app();if(app!=null&&app.store!=null)app.store.sourceEvent(sourceId(source),ok,Math.max(0,ms),Math.max(0,episodes),Math.max(0,variants),Math.max(0,quality));}
    static void recordVariant(Anime.Variant v,boolean ok,long ms,int quality){record(variantSource(v),ok,ms,0,ok?1:0,quality);}
    static int optionCount(Anime a){int n=0;if(a!=null)for(Anime.Episode e:a.episodeList)n+=Math.min(40,e.streams.size()+e.variants.size());return n;}
    static int maxQuality(Anime a){int q=0;if(a!=null)for(Anime.Episode e:a.episodeList)for(Integer k:e.streams.keySet())if(k!=null)q=Math.max(q,k);return q;}
    static ArrayList<Anime.Variant> sortVariants(Collection<Anime.Variant> rows){ArrayList<Anime.Variant> out=new ArrayList<>();if(rows!=null)for(Anime.Variant v:rows)if(v!=null)out.add(v);out.sort((a,b)->variantRank(a)-variantRank(b));return out;}
    static int variantRank(Anime.Variant v){String src=variantSource(v);int rank=1000-score(src,null);String text=(v==null?"":v.name+" "+v.player+" "+v.displayName).toLowerCase(Locale.ROOT);String pref="";boolean strict=false;int fav=-1;try{pref=YoruApp.app().store.voicePreference();strict=YoruApp.app().store.onlyPreferredVoice();fav=YoruApp.app().store.voicePriority(text);}catch(Exception ignored){}if(fav>=0)rank-=95-Math.min(70,fav*10);else if(!pref.isEmpty()&&ApiRepository.voiceMatches(pref,text))rank-=70;else if(strict)rank+=300;if(text.contains("2160")||text.contains("4k")||text.contains("uhd"))rank-=26;else if(text.contains("1440")||text.contains("2k")||text.contains("qhd"))rank-=20;else if(text.contains("1080")||text.contains("fullhd")||text.contains("full hd"))rank-=14;else if(text.contains("720"))rank-=10;else if(text.contains("480"))rank-=3;if(text.contains("субтит")||text.contains("sub"))rank+=8;if(text.contains("трейлер")||text.contains("анонс"))rank+=30;return rank;}
    static ArrayList<Anime> mergeCatalog(Collection<Anime> rows,int limit){LinkedHashMap<String,Anime> map=new LinkedHashMap<>();if(rows!=null)for(Anime a:rows){if(!Anime.valid(a))continue;String key=identity(a);Anime old=map.get(key);if(old==null){for(Map.Entry<String,Anime> e:map.entrySet())if(sameTitle(e.getValue(),a)){key=e.getKey();old=e.getValue();break;}}if(old==null)map.put(key,a);else{Anime chosen=best(old,a),extra=chosen==old?a:old;absorb(chosen,extra);map.put(key,chosen);}}ArrayList<Anime> out=new ArrayList<>(map.values());out.sort((a,b)->{int p=score(b.source,b)-score(a.source,a);if(p!=0)return p;return Double.compare(b.score,a.score);});if(limit>0&&out.size()>limit)return new ArrayList<>(out.subList(0,limit));return out;}
    private static Anime best(Anime a,Anime b){int as=score(a.source,a)+(a.poster.isEmpty()?0:8)+(a.description.isEmpty()?0:6)+(a.episodeList.isEmpty()?0:10);int bs=score(b.source,b)+(b.poster.isEmpty()?0:8)+(b.description.isEmpty()?0:6)+(b.episodeList.isEmpty()?0:10);return bs>as?b:a;}
    private static boolean sameTitle(Anime a,Anime b){if(a==null||b==null)return false;if(a.malId>0&&b.malId>0&&a.malId==b.malId)return true;if(a.anilistId>0&&b.anilistId>0&&a.anilistId==b.anilistId)return true;if(a.kpId>0&&b.kpId>0&&a.kpId==b.kpId)return true;String at=ApiRepository.plainName(a.title),ao=ApiRepository.plainName(a.original),bt=ApiRepository.plainName(b.title),bo=ApiRepository.plainName(b.original);boolean name=(!at.isEmpty()&&(at.equals(bt)||at.equals(bo)))||(!ao.isEmpty()&&(ao.equals(bt)||ao.equals(bo)));boolean year=a.year==0||b.year==0||Math.abs(a.year-b.year)<=1;return name&&year;}
    static void absorb(Anime target,Anime source){if(target==null||source==null)return;if(target.title.isEmpty())target.title=source.title;if(target.original.isEmpty())target.original=source.original;if(target.alias.isEmpty())target.alias=source.alias;if(target.poster.isEmpty())target.poster=source.poster;if(target.description.isEmpty())target.description=source.description;if(target.year==0)target.year=source.year;if(target.type.isEmpty()||"Аниме".equals(target.type))target.type=source.type;if(target.status.isEmpty())target.status=source.status;if(target.age.isEmpty())target.age=source.age;if(target.studio.isEmpty())target.studio=source.studio;if(target.episodes==0)target.episodes=source.episodes;if(target.episodesAired==0)target.episodesAired=source.episodesAired;if(target.nextEpisodeAt.isEmpty())target.nextEpisodeAt=source.nextEpisodeAt;if(target.malId==0)target.malId=source.malId;if(target.anilistId==0)target.anilistId=source.anilistId;if(target.kpId==0)target.kpId=source.kpId;if(target.libriaAlias.isEmpty())target.libriaAlias=source.libriaAlias;if(target.score==0)target.score=source.score;if(target.trailerUrl.isEmpty())target.trailerUrl=source.trailerUrl;if(target.airedDate.isEmpty())target.airedDate=source.airedDate;if(target.countries.isEmpty())target.countries=source.countries;if(target.cast.isEmpty())target.cast=source.cast;if(target.crew.isEmpty())target.crew=source.crew;if(target.ratings.isEmpty())target.ratings=source.ratings;if(target.franchise.isEmpty())target.franchise=source.franchise;if(target.durationMinutes==0)target.durationMinutes=source.durationMinutes;if(target.translationsCount==0)target.translationsCount=source.translationsCount;if(target.shikimoriOrder==0)target.shikimoriOrder=source.shikimoriOrder;for(String shot:source.screenshots)if(shot!=null&&!shot.isEmpty()&&!target.screenshots.contains(shot)&&target.screenshots.size()<12)target.screenshots.add(shot);if(target.blocked&& !source.blocked)target.blocked=false;for(String g:source.genres)if(g!=null&&!g.isEmpty()&&!target.genres.contains(g)&&target.genres.size()<30)target.genres.add(g);for(Anime r:source.related)if(Anime.valid(r)&&target.related.size()<24)target.related.add(r);}
    static String identity(Anime a){if(a==null)return "";if(a.malId>0)return "mal:"+a.malId;if(a.anilistId>0)return "ani:"+a.anilistId;if(a.kpId>0)return "kp:"+a.kpId;String n=ApiRepository.plainName((a.original.isEmpty()?a.title:a.original));if(n.isEmpty())n=ApiRepository.plainName(a.title);return n+":"+(a.year>0?a.year:0);}
    static String variantSource(Anime.Variant v){String text=((v==null?"":v.name)+" "+(v==null?"":v.player)+" "+(v==null?"":v.displayName)).toLowerCase(Locale.ROOT);return sourceId(text);}
    static String sourceId(String value){String v=value==null?"":value.trim().toLowerCase(Locale.ROOT);if(v.isEmpty())return "yoru";if(v.contains("yoru max")||v.contains("yummy")||v.contains("yani")||v.contains("cvh")||v.contains("cdnvideohub"))return "yummy";if(v.contains("anixsekai")||v.contains("anix")||v.contains("sekai")||v.contains("yoru reserve"))return "anixsekai";if(v.contains("yoru prime")||v.contains("kodik")||v.contains("aniqit"))return "kodik";if(v.contains("anilibria")||v.contains("aniliberty"))return "anilibria";if(v.contains("animevost"))return "animevost";if(v.contains("animelib ultra")||v.contains("animelib4k"))return "animelib4k";if(v.contains("animelib")||v.contains("anilib"))return "animelib";if(v.contains("animedia"))return "animedia";if(v.contains("animetka"))return "animetka";if(v.contains("anidub"))return "anidub";if(v.contains("hanime"))return "hanime";if(v.contains("yoru"))return "yoru";return v.replaceAll("[^a-z0-9_]+","");}
}
